import * as THREE from './vendor/three.module.js';
import {Game,W,H} from './engine.js';
const $=id=>document.getElementById(id),canvas=$('game'),arena=$('arena');
let renderer;
try{renderer=new THREE.WebGLRenderer({canvas,antialias:false,alpha:false,powerPreference:'low-power'});}catch(e){$('overlayTitle').textContent='WebGL unavailable';$('overlayText').textContent='Enable hardware acceleration or try a newer browser.';$('start').hidden=true;throw e;}
renderer.setPixelRatio(Math.min(devicePixelRatio,2));renderer.setClearColor(0x050a14);
const scene=new THREE.Scene(),camera=new THREE.OrthographicCamera(0,W,0,H,-100,100);camera.position.z=10;
const geom=new THREE.BoxGeometry(1,1,1),colors=['#c19bff','#77c6ff','#77c6ff','#a2ff9f'];
const materials=new Map();function mat(color){if(!materials.has(color))materials.set(color,new THREE.MeshBasicMaterial({color}));return materials.get(color);}
const patterns=[['00100100','00011000','00111100','01111110','11011011','11111111','00100100','01011010'],['00100100','01000010','11111111','11011011','11111111','00111100','01000010','10000001'],['00100100','01000010','11111111','11011011','11111111','00111100','01000010','10000001'],['00111100','01111110','11111111','11011011','11111111','00100100','01100110','10000001']];
const shipPattern=['0001000','0001000','0011100','0111110','1111111','1111111'];
function sprite(pattern,color,pixel=.8){const g=new THREE.Group();pattern.forEach((row,y)=>[...row].forEach((v,x)=>{if(v==='1'){const m=new THREE.Mesh(geom,mat(color));m.position.set((x-(row.length-1)/2)*pixel,(y-(pattern.length-1)/2)*pixel,0);m.scale.set(pixel*.93,pixel*.93,1);g.add(m);}}));scene.add(g);return g;}
const ship=sprite(shipPattern,'#a2ff9f',1),alienMeshes=[];
const ufo=sprite(['00011111000','00111111100','01111111110','11011011011','11111111111','00100100100'],'#ff829c',.9);ufo.visible=false;
const shieldMesh=new THREE.InstancedMesh(geom,mat('#68cfa4'),240),bulletMesh=new THREE.InstancedMesh(geom,mat('#dbf8d7'),100),enemyBulletMesh=new THREE.InstancedMesh(geom,mat('#ff849d'),100);// These batches begin empty and move every frame. Their cached bounds would
// otherwise cull newly spawned lasers, alien shots and shield blocks.
for (const batch of [shieldMesh, bulletMesh, enemyBulletMesh]) batch.frustumCulled = false;
scene.add(shieldMesh,bulletMesh,enemyBulletMesh);shieldMesh.instanceMatrix.setUsage(THREE.DynamicDrawUsage);
const dummy=new THREE.Object3D();function instance(mesh,i,x,y,sx,sy){dummy.position.set(x,y,0);dummy.scale.set(sx,sy,1);dummy.updateMatrix();mesh.setMatrixAt(i,dummy.matrix);}
const starCount=100,starPos=new Float32Array(starCount*3);for(let i=0;i<starCount;i++){starPos[i*3]=Math.random()*W;starPos[i*3+1]=Math.random()*H;starPos[i*3+2]=-2;}const starsGeom=new THREE.BufferGeometry();starsGeom.setAttribute('position',new THREE.BufferAttribute(starPos,3));scene.add(new THREE.Points(starsGeom,new THREE.PointsMaterial({color:0x5d7398,size:.35,transparent:true,opacity:.65})));
const lineGeom=new THREE.BufferGeometry().setFromPoints([new THREE.Vector3(3,132,0),new THREE.Vector3(97,132,0)]);scene.add(new THREE.Line(lineGeom,new THREE.LineBasicMaterial({color:0x22423b})));
let best=0;try{best=Number(localStorage.getItem('neon-invaders-best'))||0;}catch{}let sound=false,audio=null,auto=true,dragTarget,dragId=null,keys=new Set(),held=new Set(),fx=[],last=performance.now(),noticeUntil=0;
function beep(freq,duration=.06,type='square',volume=.025){if(!sound||!audio)return;const osc=audio.createOscillator(),gain=audio.createGain();osc.type=type;osc.frequency.setValueAtTime(freq,audio.currentTime);osc.frequency.exponentialRampToValueAtTime(Math.max(40,freq*.55),audio.currentTime+duration);gain.gain.setValueAtTime(volume,audio.currentTime);gain.gain.exponentialRampToValueAtTime(.001,audio.currentTime+duration);osc.connect(gain);gain.connect(audio.destination);osc.start();osc.stop(audio.currentTime+duration);}
function unlock(){if(!audio){const AC=window.AudioContext||window.webkitAudioContext;if(AC)audio=new AC();}if(audio?.state==='suspended')audio.resume().catch(()=>{});}
function burst(data,color){for(let i=0;i<12;i++){const m=new THREE.Mesh(geom,mat(color));m.position.set(data.x,data.y,1);m.scale.set(.65,.65,.65);scene.add(m);fx.push({m,vx:(Math.random()-.5)*35,vy:(Math.random()-.5)*35,life:.45});}}
function clearInput(){keys.clear();held.clear();dragTarget=undefined;dragId=null;document.querySelectorAll('.held').forEach(b=>b.classList.remove('held'));}
const game=new Game({event:(type,data)=>{if(type==='shoot')beep(850,.045,'square',.012);if(type==='kill'){burst(data,colors[data.row]);beep(180,.09);}if(type==='bonus'){burst(data,'#ff829c');beep(650,.25,'sine');$('waveNotice').textContent='+150 BONUS';noticeUntil=performance.now()+1000;}if(type==='hit'){burst(data,'#a2ff9f');beep(90,.3,'sawtooth',.06);}if(type==='wave'){alienMeshes.forEach(m=>scene.remove(m));alienMeshes.length=0;game.aliens.forEach(a=>alienMeshes.push(sprite(patterns[a.row],colors[a.row])));$('waveNotice').textContent=`WAVE ${String(data).padStart(2,'0')}`;noticeUntil=performance.now()+1300;}if(type==='clear'){beep(700,.2,'triangle');$('waveNotice').textContent='SECTOR CLEAR';noticeUntil=performance.now()+1500;}if(type==='over'){clearInput();saveBest();showOverlay('MISSION OVER',`SCORE ${String(game.score).padStart(5,'0')}`,`You held the line for ${game.wave} wave${game.wave===1?'':'s'}.<br>Ready for another run?`,'PLAY AGAIN ↗');$('pause').disabled=true;}}});
function saveBest(){if(game.score>best){best=game.score;try{localStorage.setItem('neon-invaders-best',String(best));}catch{}}}
function showOverlay(overline,title,text,button){$('overlay').hidden=false;$('overline').textContent=overline;$('overlayTitle').textContent=title;$('overlayText').innerHTML=text;$('start').textContent=button;$('overlayHint').textContent=game.mode==='paused'?'TAKE A BREATH. THE GALAXY CAN WAIT.':'3 LIVES · ENDLESS WAVES · ONE PLANET';}
function togglePause(force=false){if(game.mode==='playing'){game.pause();clearInput();saveBest();showOverlay('MISSION PAUSED','HOLDING POSITION','Your mission is safe.<br>Resume when you’re ready.','RESUME MISSION ↗');$('pause').textContent='▶';$('pause').setAttribute('aria-label','Resume game');}else if(!force&&game.mode==='paused'){game.resume();$('overlay').hidden=true;$('pause').textContent='Ⅱ';$('pause').setAttribute('aria-label','Pause game');last=performance.now();}}
$('start').addEventListener('click',()=>{unlock();clearInput();if(game.mode==='paused')togglePause();else{fx.forEach(p=>scene.remove(p.m));fx=[];game.start();$('overlay').hidden=true;$('pause').disabled=false;$('pause').textContent='Ⅱ';$('pause').setAttribute('aria-label','Pause game');last=performance.now();}});
$('pause').onclick=()=>togglePause();$('sound').onclick=()=>{unlock();sound=!sound;$('sound').textContent=sound?'SOUND ON':'SOUND OFF';$('sound').setAttribute('aria-pressed',String(sound));$('sound').setAttribute('aria-label',sound?'Mute sound':'Enable sound');if(sound)beep(550,.1,'sine');};$('auto').onclick=()=>{auto=!auto;$('auto').setAttribute('aria-pressed',String(auto));};
for(const id of ['left','right','fire']){const button=$(id);const release=e=>{held.delete(id);button.classList.remove('held');};button.addEventListener('pointerdown',e=>{e.preventDefault();unlock();button.setPointerCapture(e.pointerId);held.add(id);button.classList.add('held');});button.addEventListener('pointerup',release);button.addEventListener('pointercancel',release);button.addEventListener('lostpointercapture',release);}
canvas.addEventListener('pointerdown',e=>{if(game.mode!=='playing')return;dragId=e.pointerId;canvas.setPointerCapture(e.pointerId);dragTarget=toWorld(e.clientX);unlock();});canvas.addEventListener('pointermove',e=>{if(e.pointerId===dragId)dragTarget=toWorld(e.clientX);});for(const name of ['pointerup','pointercancel','lostpointercapture'])canvas.addEventListener(name,()=>{dragId=null;dragTarget=undefined;});function toWorld(x){const r=canvas.getBoundingClientRect();return (x-r.left)/r.width*W;}
window.addEventListener('keydown',e=>{if(['ArrowLeft','ArrowRight',' ','a','d','A','D','p','P','Escape','Enter'].includes(e.key)){if(e.target instanceof HTMLButtonElement&&(e.key==='Enter'||e.key===' '))return;e.preventDefault();if(!e.repeat&&['p','P','Escape'].includes(e.key))togglePause();keys.add(e.key.toLowerCase());}});window.addEventListener('keyup',e=>keys.delete(e.key.toLowerCase()));window.addEventListener('blur',()=>togglePause(true));document.addEventListener('visibilitychange',()=>{if(document.hidden)togglePause(true);});
new ResizeObserver(()=>{renderer.setSize(arena.clientWidth,arena.clientHeight,false);}).observe(arena);
window.addEventListener('pagehide',saveBest);canvas.addEventListener('webglcontextlost',e=>{e.preventDefault();togglePause(true);$('overlayText').textContent='Graphics paused. Reload this page to restore the game.';});
function render(now){requestAnimationFrame(render);const dt=Math.min((now-last)/1000,.04);last=now;const move=Number(keys.has('arrowright')||keys.has('d')||held.has('right'))-Number(keys.has('arrowleft')||keys.has('a')||held.has('left'));game.step(dt,{move,target:move?undefined:dragTarget,fire:auto||keys.has(' ')||held.has('fire')});ship.position.set(game.player.x,game.player.y,0);ship.visible=game.mode!=='over'&&!(game.invincible>0&&Math.floor(now/90)%2===0);game.aliens.forEach((a,i)=>{const m=alienMeshes[i];if(m){m.visible=a.alive;m.position.set(a.x,a.y,0);m.scale.x=1+Math.sin(game.time*5)*.025;}});let si=0;for(const s of game.shields)if(s.alive)instance(shieldMesh,si++,s.x,s.y,1.35,1.35);shieldMesh.count=si;shieldMesh.instanceMatrix.needsUpdate=true;let bi=0,ei=0;for(const b of game.bullets){if(b.friendly&&bi<100)instance(bulletMesh,bi++,b.x,b.y,.65,3);else if(!b.friendly&&ei<100)instance(enemyBulletMesh,ei++,b.x,b.y,.8,2.6);}bulletMesh.count=bi;enemyBulletMesh.count=ei;bulletMesh.instanceMatrix.needsUpdate=true;enemyBulletMesh.instanceMatrix.needsUpdate=true;ufo.visible=!!game.ufo;if(game.ufo)ufo.position.set(game.ufo.x,game.ufo.y,0);if(game.mode==='playing')for(const p of fx){p.life-=dt;p.m.position.x+=p.vx*dt;p.m.position.y+=p.vy*dt;p.m.scale.multiplyScalar(.97);}fx=fx.filter(p=>{if(p.life<=0){scene.remove(p.m);return false;}return true;});$('score').textContent=String(game.score).padStart(5,'0');$('best').textContent=String(Math.max(best,game.score)).padStart(5,'0');$('wave').textContent=String(game.wave).padStart(2,'0');$('lives').textContent=Array(Math.max(0,game.lives)).fill('▲').join(' ')||'—';$('lives').setAttribute('aria-label',`${game.lives} lives`);if(now>noticeUntil)$('waveNotice').textContent='';renderer.render(scene,camera);}
requestAnimationFrame(render);
